#!/usr/bin/env node
/**
 * Synthetic Jira user export for the Harbourline Freight readiness assessment.
 *
 * The REAL users.csv is under NDA and was not shared. This generator stands in
 * for it: same columns, same faults, a fixed count and a seeded RNG, so the
 * cleanup scripts you hand over can be developed and demonstrated against
 * something reproducible.
 *
 * Usage:  node scripts/gen-users.js [count] [seed]   (defaults: 400 42)
 * Output: data/users.csv
 *
 * The faults mirror the kickoff notes (2026-09-27):
 *   - case-only duplicate emails   (John.Smith@ vs john.smith@)
 *   - ~30 users with no email      (blank email, and a blank username too)
 *   - svc-* service accounts       (machine accounts, no real human behind them)
 *   - inactive users               (last_login 1–6 years back)
 *   - group columns jira-software-users and jira-administrators
 *
 * ZERO dependencies: Node standard library only. Run on any modern Node.
 */

'use strict';

const fs = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Arguments
// ---------------------------------------------------------------------------
const COUNT = parseInt(process.argv[2], 10) || 400;
const SEED = parseInt(process.argv[3], 10) || 42;
const OUT = path.join(__dirname, '..', 'data', 'users.csv');

// ---------------------------------------------------------------------------
// Seeded RNG — mulberry32 (small, deterministic, no dependency)
// ---------------------------------------------------------------------------
function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rng = mulberry32(SEED);
const rand = () => rng();
const pick = (arr) => arr[Math.floor(rand() * arr.length)];
const int = (min, max) => min + Math.floor(rand() * (max - min + 1));
const chance = (p) => rand() < p;

// ---------------------------------------------------------------------------
// Vocabulary
// ---------------------------------------------------------------------------
const FIRST = [
  'Aoife', 'Marek', 'John', 'Mary', 'James', 'Emma', 'Liam', 'Olivia', 'Noah', 'Ava',
  'Ethan', 'Sophie', 'Lucas', 'Mia', 'Henry', 'Isla', 'Oliver', 'Ella', 'George', 'Chloe',
  'Jack', 'Amelia', 'Ben', 'Grace', 'Tom', 'Faye', 'Dan', 'Holly', 'Mark', 'Linda',
  'Peter', 'Sarah', 'Paul', 'Claire', 'David', 'Rachel', 'Chris', 'Helen', 'Steve', 'Nicole',
  'Gareth', 'Cerys', 'Rhys', 'Catie', 'Owen', 'Elin', 'Dylan', 'Megan', 'Evan', 'Seren',
];
const LAST = [
  'Brennan', 'O\u2019Connell', 'Smith', 'Jones', 'Taylor', 'Brown', 'Davies', 'Williams',
  'Evans', 'Roberts', 'Price', 'Lewis', 'Hughes', 'Thomas', 'Walker', 'Robinson',
  'Clarke', 'Richardson', 'Mitchell', 'Chapman', 'Turner', 'Phillips', 'Campbell',
  'Patterson', 'Hamilton', 'Clark', 'Wilson', 'Murray', 'Wright', 'Mason',
  'Hughes', 'Rees', 'Lewis', 'Davies', 'Jones', 'Williams', 'Roberts', 'Evans',
];
const DOMAINS = ['harbourlinefreight.com', 'hf-logistics.com', 'harbourline.com'];
const SVC_NAMES = [
  'svc-jenkins', 'svc-github', 'svc-slack', 'svc-sabre', 'svc-bpc', 'svc-erp',
  'svc-webhook', 'svc-cli', 'svc-sync', 'svc-scheduler', 'svc-sentinel', 'svc-teleport',
];

// A name with a few casing variants, so duplicates are case-only, not real people.
function casingVariants(first, last) {
  const variants = new Set();
  variants.add(first.charAt(0).toUpperCase() + first.slice(1).toLowerCase());
  variants.add(first.toLowerCase());
  variants.add(first.toUpperCase());
  variants.add(first);
  return Array.from(variants);
}

function isoDate(y, m, d) {
  const pad = (n) => String(n).padStart(2, '0');
  return `${y}-${pad(m)}-${pad(d)}`;
}

// ---------------------------------------------------------------------------
// Build the user list
// ---------------------------------------------------------------------------
const rows = [];
const usedRealNames = new Set();
let realIdx = 0;
let noEmailCount = 0;
let dupCount = 0;

// A realistic-ish spread: mostly active, a long tail of dormant accounts.
function randomLastLogin() {
  const r = rand();
  let daysAgo;
  if (r < 0.55) daysAgo = int(0, 90);          // active
  else if (r < 0.75) daysAgo = int(90, 180);    // lapsed
  else if (r < 0.88) daysAgo = int(180, 365);   // stale (inside 24-month cutoff)
  else daysAgo = int(365, 365 * 6);             // years ago — the inactive tail
  const dt = new Date(2026, 8, 28);             // 2026-09-28, today
  dt.setDate(dt.getDate() - daysAgo);
  const y = dt.getUTCFullYear();
  const m = dt.getUTCMonth() + 1;
  const d = dt.getUTCDate();
  return isoDate(y, m, d);
}

// How many duplicate pairs to plant (~18% of the population, like a junk AD).
const TARGET_DUP_PAIRS = Math.round(COUNT * 0.18);
const TARGET_NO_EMAIL = Math.round(COUNT * 0.075);   // ~30 at 400
const SVC_COUNT = int(10, 16);

// 1. Service accounts first — they never have a real name or login history.
for (let i = 0; i < SVC_COUNT; i++) {
  const svc = pick(SVC_NAMES);
  rows.push({
    username: svc,
    display_name: `${svc} (integration)`,
    email: `${svc}@harbourlinefreight.com`,
    active: true,
    last_login: chance(0.8) ? randomLastLogin() : isoDate(2019, int(1, 12), int(1, 28)),
    groups: 'jira-software-users',
  });
}

// 2. Real users, with a case-duplicate twin planted ~18% of the time.
while (rows.length < COUNT) {
  // Pick a name not already used (so dupes are case-only, never literal repeats).
  let first, last, key;
  let guard = 0;
  do {
    first = pick(FIRST);
    last = pick(LAST);
    key = `${first[0].toUpperCase()}${last[0].toUpperCase()}`;
    guard++;
  } while (usedRealNames.has(key) && guard < 50);
  if (guard >= 50) {
    key += int(0, 999);
  }
  usedRealNames.add(key);

  const f = pick(casingVariants(first));
  const l = pick(casingVariants(last));
  const domain = pick(DOMAINS);
  const email = `${f}.${l}@${domain}`.toLowerCase();
  const isAdmin = chance(0.06);
  const groups = isAdmin ? 'jira-software-users,jira-administrators' : 'jira-software-users';

  rows.push({
    username: `${f}.${l}`.toLowerCase(),
    display_name: `${first[0].toUpperCase()}${first.slice(1)} ${last}`,
    email,
    active: true,
    last_login: randomLastLogin(),
    groups,
  });

  // Plant a case-only duplicate twin with an independent (often different) login date.
  if (dupCount < TARGET_DUP_PAIRS && chance(0.18)) {
    dupCount++;
    const twinFirst = pick(casingVariants(first)); // a DIFFERENT casing than the first row
    const twinLast = pick(casingVariants(last));
    const twin = `${twinFirst}.${twinLast}@${domain}`.toLowerCase();
    rows.push({
      username: `${twinFirst}.${twinLast}`.toLowerCase(),
      display_name: `${first[0].toUpperCase()}${first.slice(1)} ${last}`,
      email: twin,
      active: true,
      last_login: randomLastLogin(),
      groups,
    });
  }
}

// 3. Sprinkle ~30 users with NO email (and a blank username) — the contractor/junk pile.
for (let i = 0; i < TARGET_NO_EMAIL && rows.length < COUNT + TARGET_NO_EMAIL; i++) {
  const first = pick(FIRST);
  const last = pick(LAST);
  noEmailCount++;
  rows.push({
    username: '',
    display_name: `${first[0].toUpperCase()}${first.slice(1)} ${last}`,
    email: '',
    active: chance(0.2),
    last_login: chance(0.5) ? randomLastLogin() : isoDate(int(2018, 2024), int(1, 12), int(1, 28)),
    groups: 'jira-software-users',
  });
}

// ---------------------------------------------------------------------------
// Emit CSV
// ---------------------------------------------------------------------------
function csvCell(v) {
  const s = String(v == null ? '' : v);
  return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}

fs.mkdirSync(path.dirname(OUT), { recursive: true });
const header = 'username,display_name,email,active,last_login,groups';
const body = rows.map((r) =>
  [r.username, r.display_name, r.email, r.active, r.last_login, r.groups]
    .map(csvCell)
    .join(',')
).join('\n');
fs.writeFileSync(OUT, `${header}\n${body}\n`, 'utf8');

// Summary, so a run is self-documenting.
const withDupKey = new Set();
const dupEmails = new Set();
for (const r of rows) {
  if (!r.email) continue;
  const k = r.email.toLowerCase();
  if (withDupKey.has(k)) dupEmails.add(k);
  withDupKey.add(k);
}
console.log(`Wrote ${OUT}`);
console.log(`  rows:          ${rows.length}`);
console.log(`  no-email:      ${rows.filter((r) => !r.email).length}`);
console.log(`  svc accounts:  ${rows.filter((r) => r.username.startsWith('svc-')).length}`);
console.log(`  dup emails:    ${dupEmails.size} addresses shared by 2+ rows`);
console.log(`  admins:        ${rows.filter((r) => r.groups.includes('jira-administrators')).length}`);
console.log(`  (seed=${SEED} count=${COUNT} — rerun with different args for a different population)`);

